    pub(crate) fn compare_diagnostic_event_needs(
        &self,
        other: &Document,
        a: &DiagnosticEventNeeds,
        b: &DiagnosticEventNeeds,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_capability_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_deferring_fid_refs();
        let list_b = b.get_deferring_fid_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DEFERRING_FID_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.DEFERRING_FID_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.DEFERRING_FID_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.DEFERRING_FID_REFS[{index}]"))?;
        }
        if a.get_diag_event_debounce_algorithm() != b.get_diag_event_debounce_algorithm() {
            return Err(format!("{path}: DIAG_EVENT_DEBOUNCE_ALGORITHM mismatch"));
        }
        if a.get_inhibiting_fid_ref() != b.get_inhibiting_fid_ref() {
            return Err(format!("{path}: INHIBITING_FID_REF mismatch"));
        }
        let list_a = a.get_inhibiting_secondary_fid_refs();
        let list_b = b.get_inhibiting_secondary_fid_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: INHIBITING_SECONDARY_FID_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.INHIBITING_SECONDARY_FID_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!(
                    "{path}.INHIBITING_SECONDARY_FID_REFS[{index}]: id not found in other arena"
                )
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.INHIBITING_SECONDARY_FID_REFS[{index}]"),
            )?;
        }
        if a.get_prestored_freezeframe_stored_in_nvm()
            != b.get_prestored_freezeframe_stored_in_nvm()
        {
            return Err(format!(
                "{path}: PRESTORED_FREEZEFRAME_STORED_IN_NVM mismatch"
            ));
        }
        if a.get_uses_monitor_data() != b.get_uses_monitor_data() {
            return Err(format!("{path}: USES_MONITOR_DATA mismatch"));
        }
        Ok(())
    }

