    pub(crate) fn compare_supervised_entity_needs(
        &self,
        other: &Document,
        a: &SupervisedEntityNeeds,
        b: &SupervisedEntityNeeds,
        path: &str,
    ) -> Result<(), String> {
        self.compare_service_needs(other, a.base(), b.base(), path)?;
        if a.get_activate_at_start() != b.get_activate_at_start() {
            return Err(format!("{path}: ACTIVATE_AT_START mismatch"));
        }
        let list_a = a.get_checkpoints_refs();
        let list_b = b.get_checkpoints_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CHECKPOINTS_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.CHECKPOINTS_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.CHECKPOINTS_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.CHECKPOINTS_REFS[{index}]"))?;
        }
        if a.get_enable_deactivation() != b.get_enable_deactivation() {
            return Err(format!("{path}: ENABLE_DEACTIVATION mismatch"));
        }
        if a.get_expected_alive_cycle() != b.get_expected_alive_cycle() {
            return Err(format!("{path}: EXPECTED_ALIVE_CYCLE mismatch"));
        }
        if a.get_max_alive_cycle() != b.get_max_alive_cycle() {
            return Err(format!("{path}: MAX_ALIVE_CYCLE mismatch"));
        }
        if a.get_min_alive_cycle() != b.get_min_alive_cycle() {
            return Err(format!("{path}: MIN_ALIVE_CYCLE mismatch"));
        }
        if a.get_tolerated_failed_cycles() != b.get_tolerated_failed_cycles() {
            return Err(format!("{path}: TOLERATED_FAILED_CYCLES mismatch"));
        }
        Ok(())
    }

