    pub(crate) fn compare_transient_fault(
        &self,
        other: &Document,
        a: &TransientFault,
        b: &TransientFault,
        path: &str,
    ) -> Result<(), String> {
        self.compare_traced_failure(other, a.base(), b.base(), path)?;
        let list_a = a.get_possible_error_reactions();
        let list_b = b.get_possible_error_reactions();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: POSSIBLE_ERROR_REACTIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.possible_error_reactions.get(*x).ok_or_else(|| {
                format!("{path}.POSSIBLE_ERROR_REACTIONS[{index}]: id not found in own arena")
            })?;
            let y = other.possible_error_reactions.get(*y).ok_or_else(|| {
                format!("{path}.POSSIBLE_ERROR_REACTIONS[{index}]: id not found in other arena")
            })?;
            self.compare_possible_error_reaction(
                other,
                x,
                y,
                &format!("{path}.POSSIBLE_ERROR_REACTIONS[{index}]"),
            )?;
        }
        Ok(())
    }

